  while (i < musicString.length) {
    if (musicString[i] == ' ') {
      i++;
      continue;
    }

    int noteValue = 0;
    bool isSharp = false;
    int duration = 1;

    // Parse the note character
    switch (musicString[i]) {
      case 'A':
        noteValue = 0; break;
      case 'B':
        noteValue = 2; break;
      case 'C':
        noteValue = 4; break;
      case 'D':
        noteValue = 5; break;
      case 'E':
        noteValue = 7; break;
      case 'F':
        noteValue = 9; break;
      case 'G':
        noteValue = 11; break;
      default:
        throw FormatException('Invalid note');
    }

    i++;

    // Check for sharp or flat
    if (i < musicString.length && (musicString[i] == '#' || musicString[i] == ',')) {
      if (musicString[i] == '#') {
        isSharp = true;
      } else {
        isSharp = false; // Flat can be treated as a different value, but here it's just not used
      }
      i++;
    }

    // Determine the duration based on subsequent characters
    if (i < musicString.length && (musicString[i] == 'w' || musicString[i] == 'h')) {
      if (musicString[i] == 'w') {
        duration = 3; // Whole note
      } else {
        duration = 2; // Half note
      }
      i++;
    }

    // Calculate frequency and add to result
    double freq = getFrequency(noteValue + (isSharp ? 1 : 0));
    for (var _ in List.filled(duration, null)) {
      result.add(freq.toInt());
    }
  }

  return result;
}

double getFrequency(int semitoneOffset) {
  const A4Freq = 440.0;
  const A4Semitone = 69;

  return A4Freq * Math.pow(2.0, (semitoneOffset - A4Semitone) / 12.0);
}
