int hexKey(String num) {
  int len = num.length;
  if (len == 0 || len % 2 != 0) return 0;

  List<int> bytes = Uint8List.fromList(num.codeUnits);
  for (int i = 0; i < len; i += 2) {
    int a = bytes[i] & 0xFF;
    int b = bytes[i + 1] & 0xFF;
    int value = ((a << 4) | b) & 0xFFFF;
    if (value > 0x7FFF) value -= 0x10000;
    bytes[i] = value >> 8;
    bytes[i + 1] = value & 0xFF;
  }

  int result = 0;
  for (var byte in bytes) {
    result ^= byte ^ (byte >> 3);
  }
  return result;
}
