import 'dart:math';

int closestInteger(String value) {
  int sign = 1;
  if (value.startsWith('-')) {
    sign = -1;
    value = value.substring(1);
  }

  bool isDecimal = false;
  List<String> parts = value.split('.');
  if (parts.length > 1) {
    isDecimal = true;
    value = parts[0];
  }

  int integerPart = int.parse(value);

  if (!isDecimal) return sign * integerPart;

  String fractionalPart = parts[1];

  // Check for exponent notation and handle it accordingly
  if (fractionalPart.contains('e') || fractionalPart.contains('E')) {
    // Handle scientific notation, e.g., "1.23456789e+1"
    final expParts = fractionalPart.split(RegExp(r'[eE]'));
    final coefficient = expParts[0];
    final exponent = int.tryParse(expParts[1]);

    if (exponent != null && exponent >= 0) {
      // Truncate to the number of digits in the coefficient based on the exponent
      final coeffDigits = coefficient.replaceAll(RegExp(r'[^0-9]'), '');
      final truncIndex = min(exponent + 1, coeffDigits.length);

      if (truncIndex < coeffDigits.length) {
        // If there are more digits than needed, truncate them
        return sign * int.parse(coeffDigits.substring(0, truncIndex));
      } else {
        // Otherwise, just parse the whole coefficient as is
        return sign * int.parse(coefficient);
      }
    }
  }

  // For regular decimal numbers without exponents
  int length = fractionalPart.length;
  int cutoffIndex = max(0, length - 1); // Take all but last digit

  // Trim trailing zeros from fractional part before processing
  while (cutoffIndex > 0 && fractionalPart[cutoffIndex - 1] == '0') {
    cutoffIndex--;
  }

  if (cutoffIndex <= 0) {
    // No non-zero digits after decimal point; just use integer part
    return sign * integerPart;
  }

  // Extract the truncated part
  String truncatedFraction = fractionalPart.substring(0, cutoffIndex).trim();
  if (truncatedFraction.isEmpty) {
    return sign * integerPart;
  }

  // Determine whether to round up or down
  bool shouldRoundUp = (cutoffIndex < fractionalPart.length) &&
                      (fractionalPart[cutoffIndex] >= '5');

  if (shouldRoundUp) {
    int roundedValue = integerPart + 1;
    // Check if adding one would overflow beyond maximum int
    if (roundedValue > int.max) {
      throw RangeError.value("Value exceeds maximum integer");
    }
    return sign * roundedValue;
  } else {
    return sign * integerPart;
  }
