import 'dart:math';

List<int> minPath(List<List<int>> grid, int k) {
  final rows = grid.length;
  final cols = grid[0].length;

  if (rows == 0 || cols == 0) return [];

  // Directions for movement: right and down
  final directions = [Vector2(1, 0), Vector2(0, 1)];

  // Priority queue to store (currentSum, pathLength, row, col)
  final pq = PriorityQueue<QueueEntry>((a, b) => a.currentSum.compareTo(b.currentSum));
  final visited = List.generate(rows * cols, (_) => <int>{});

  // Start from the top-left corner with initial sum as grid[0][0]
  pq.add(QueueEntry(grid[0][0], 1, 0, 0));

  while (pq.isNotEmpty) {
    final entry = pq.removeFirst();
    final currentSum = entry.currentSum;
    final steps = entry.pathLength;
    final r = entry.row;
    final c = entry.col;

    // Check if we have reached the bottom-right corner
    if (r == rows - 1 && c == cols - 1) {
      if (steps <= k) {
        return entry.getPath(); 
      }
      continue;
    }

    // If the number of steps is already more than k, skip this path
    if (steps > k) continue;

    // Explore all possible paths
    for (final dir in directions) {
      final newRow = r + dir.x;
      final newCol = c + dir.y;

      // Ensure within bounds
      if (newRow >= 0 && newRow < rows && newCol >= 0 && newCol < cols) {
        final newPath = [...entry.path];
        newPath.add(newRow * cols + newCol);
