  int count = 0;
  while (queue.isNotEmpty) {
    final current = queue.removeFirst();

    if (current > arr.length || current < 1) continue;

    final pos = current - 1;
    if (arr[pos] == current) {
      count++;
      continue;
    }

    // Check if the value at current's position is valid
    final nextValue = arr[current - 1];
    if (nextValue > arr.length || nextValue < 1) continue;

    queue.add(nextValue);
  }

  return count;
}
