bool simplify(String x, String n) {
  int lenX = x.length;
  int lenN = n.length;

  if (lenX < lenN || (lenX == lenN && x.compareTo(n) <= 0)) {
    return false;
  }

  List<int> digitsX = x.codeUnits.toList();
  List<int> digitsN = n.codeUnits.toList();

  // Convert to big integers
  BigInt numX = _stringToBigInt(digitsX);
  BigInt numN = _stringToBigInt(digitsN);

  // Check divisibility
  bool divisible = numX % numN == BigInt.zero;

  if (!divisible) {
    return false;
  }

  // Simplify by dividing both numbers by their GCD
  BigInt gcdValue = _gcd(numX, numN);
  numX = numX ~/ gcdValue;
  numN = numN ~/ gcdValue;

  // Convert back to strings and check for leading zeros
  String simplifiedX = _bigIntToString(numX);
  String simplifiedN = _bigIntToString(numN);

  return simplifiedX != "0" && simplifiedN != "0";
}

// Helper function to convert a string of ASCII codes to a BigInt
BigInt _stringToBigInt(List<int> digits) {
  BigInt result = BigInt.zero;
  for (int i = 0; i < digits.length; ++i) {
    result = result * BigInt.from(10) + BigInt.from(digits[i] - 48);
  }
  return result;
}

// Helper function to compute the greatest common divisor using Euclidean algorithm
BigInt _gcd(BigInt a, BigInt b) {
  while (b != BigInt.zero) {
    var temp = b;
    b = a % b;
    a = temp;
  }
  return a;
}

// Helper function to convert a BigInt to its string representation without leading zeros
String _bigIntToString(BigInt number) {
  if (number == BigInt.zero) {
    return "0";
  }

  StringBuffer buffer = StringBuffer();
  while (number > BigInt.one) {
    buffer.write(number % BigInt.from(10));
    number = number ~/ BigInt.from(10);
  }

  // Reverse the digits
  Iterable<String> reversedDigits = buffer.toString().split('').reversed;
  String result = reversedDigits.join('');
  return result;
}
