  // For example, longer names are stronger, and more letters at the end are better.
  int length = extension.length;
  int letterCount = 0;

  for (var i = 0; i < length; i++) {
    final char = extension[i];
    if (_isLetter(char)) {
      letterCount++;
    } else if (letterCount > 0 && _isDigit(char)) {
      break;
    }
  }

  return length * 10 + letterCount;
}

bool _isLetter(String c) => c.codeUnitAt(0).toLowerCase() >= 'a'.codeUnitAt(0) &&
       c.codeUnitAt(0).toUpperCase() <= 'z'.codeUnitAt(0);

bool _isDigit(String c) => c.codeUnitAt(0) >= '0'.codeUnitAt(0) &&
        c.codeUnitAt(0) <= '9'.codeUnitAt(0);
}
